//! The one sample every install can have (#1816): `POST /api/samples/{name}`.
//!
//! The rows are generated by the engine, deterministic and about 10 000, so the sample works on
//! any profile and in an air-gapped install. Everything runs as the caller (`trino::execute_from`),
//! so the catalog's own grants decide whether the schema and the table may be created; Nova adds
//! no permission of its own and never drops anything (the public `demo` person may create but not
//! drop, measured 2026-11-26).

use std::sync::Arc;

use axum::{
    Extension, Json,
    extract::{Path, Query, State},
    http::StatusCode,
    response::{IntoResponse, Response},
};
use serde::Serialize;
use utoipa::ToSchema;

use crate::AppState;
use crate::auth::Principal;
use crate::catalog::{CatalogParam, catalog_scope};
use crate::data::quote_ident;
use crate::trino::{error_status, execute_from};

/// The samples this server offers, in the order a refusal names them.
pub const SAMPLES: [&str; 1] = ["trips"];

/// The schema a sample is created in: `<catalog>.samples.<name>`.
pub const SAMPLE_SCHEMA: &str = "samples";

/// The number of rows `trips` has on every install.
pub const TRIPS_ROWS: i64 = 10_000;

/// `CREATE TABLE IF NOT EXISTS <catalog>.samples.trips AS …`: deterministic, generated data.
///
/// Every function is deterministic (`sequence`, `date_add`, `element_at`, `%`) and the table is
/// measured on the lab (2026-11-26): 10 rows answered `count(*)=10`, `zone=university`.
pub fn trips_sql(catalog: &str) -> String {
    format!(
        "CREATE TABLE IF NOT EXISTS {cat}.{schema}.trips AS SELECT \
         t.id AS trip_id, \
         date_add('minute', t.id * 7, TIMESTAMP '2024-01-01 00:00:00') AS pickup_time, \
         CAST(t.id % 24 AS INTEGER) AS hour_of_day, \
         CAST(1 + (t.id % 37) / 10.0 AS DOUBLE) AS distance_km, \
         CAST(8.5 + (t.id % 53) / 10.0 AS DOUBLE) AS fare, \
         CAST((t.id % 7) / 10.0 AS DOUBLE) AS tip, \
         element_at(ARRAY['airport','midtown','harbor','station','market','park','university','riverside'], \
                    CAST(t.id % 8 AS INTEGER) + 1) AS zone \
         FROM UNNEST(sequence(1, {rows})) AS t(id)",
        cat = quote_ident(catalog),
        schema = quote_ident(SAMPLE_SCHEMA),
        rows = TRIPS_ROWS,
    )
}

/// Whether `<catalog>.samples.trips` exists, asked of the catalog's own `information_schema`.
fn exists_sql(catalog: &str) -> String {
    format!(
        "SELECT count(*) FROM {}.information_schema.tables \
         WHERE table_schema = '{}' AND table_name = 'trips'",
        quote_ident(catalog),
        SAMPLE_SCHEMA
    )
}

/// The row count of `<catalog>.samples.trips` (only called once it exists).
fn count_sql(catalog: &str) -> String {
    format!(
        "SELECT count(*) FROM {}.{}.trips",
        quote_ident(catalog),
        quote_ident(SAMPLE_SCHEMA)
    )
}

/// `POST /api/samples/{name}` answer.
#[derive(Debug, Serialize, ToSchema)]
#[serde(rename_all = "camelCase")]
pub struct SampleLoaded {
    /// `true` when this call created the table; `false` when it was already there.
    pub created: bool,
    /// The catalog the sample was loaded into.
    pub catalog: String,
    /// The schema: always `samples`.
    pub namespace: String,
    /// The table name: `trips`.
    pub table: String,
    /// The row count after the call.
    pub rows: i64,
}

#[utoipa::path(
    post,
    operation_id = "samples_load",
    path = "/api/samples/{name}",
    tag = "public",
    description = "Load one generated sample table as the caller. `trips` is the only sample: \
        about 10 000 deterministic rows in `<catalog>.samples.trips`, generated by the engine, so \
        it works on every profile and in an air-gapped install. Idempotent: a second call creates \
        nothing and answers `created: false`. `?catalog=` picks the catalog; omitted, the caller's \
        default one is used. Nothing is ever dropped.",
    params(
        ("name" = String, Path, description = "Sample name; `trips` is the only one"),
        CatalogParam,
    ),
    responses(
        (status = 201, description = "The sample was created; `rows` is its row count", body = SampleLoaded),
        (status = 200, description = "The sample was already there; `created` is false", body = SampleLoaded),
        (status = 400, description = "The engine refused the statement, or the catalog name is invalid", body = crate::openapi::ErrorResponse),
        (status = 403, description = "The caller may not browse that catalog", body = crate::openapi::ErrorResponse),
        (status = 404, description = "No such sample, or no such catalog", body = crate::openapi::ErrorResponse),
        (status = 502, description = "The query engine is not reachable", body = crate::openapi::ErrorResponse),
        (status = 401, description = "Not signed in", body = crate::openapi::ErrorResponse),
    )
)]
pub async fn load(
    State(s): State<Arc<AppState>>,
    Path(name): Path<String>,
    Query(q): Query<CatalogParam>,
    caller: Option<Extension<Principal>>,
) -> Response {
    let caller = caller.as_ref().map(|c| &c.0);
    if !SAMPLES.contains(&name.as_str()) {
        return (
            StatusCode::NOT_FOUND,
            Json(serde_json::json!({
                "error": format!("no such sample: {name} — the samples are: {}", SAMPLES.join(", "))
            })),
        )
            .into_response();
    }
    let (catalog, _) = match catalog_scope(&s, caller, q.catalog.as_deref()).await {
        Ok(scope) => scope,
        Err(response) => return response,
    };
    let exists = match execute_from(&s, exists_sql(&catalog), caller, "nova-samples").await {
        Ok(answer) => {
            answer
                .rows
                .first()
                .and_then(|row| row.first())
                .and_then(|v| v.as_i64())
                .unwrap_or(0)
                > 0
        }
        Err(e) => {
            return (error_status(&e), Json(serde_json::json!({ "error": e }))).into_response();
        }
    };
    if !exists {
        let schema_sql = format!(
            "CREATE SCHEMA IF NOT EXISTS {}.{}",
            quote_ident(&catalog),
            quote_ident(SAMPLE_SCHEMA)
        );
        for sql in [schema_sql, trips_sql(&catalog)] {
            if let Err(e) = execute_from(&s, sql, caller, "nova-samples").await {
                return (error_status(&e), Json(serde_json::json!({ "error": e }))).into_response();
            }
        }
    }
    let rows = match execute_from(&s, count_sql(&catalog), caller, "nova-samples").await {
        Ok(answer) => answer
            .rows
            .first()
            .and_then(|row| row.first())
            .and_then(|v| v.as_i64())
            .unwrap_or(0),
        Err(e) => {
            return (error_status(&e), Json(serde_json::json!({ "error": e }))).into_response();
        }
    };
    let body = SampleLoaded {
        created: !exists,
        catalog,
        namespace: SAMPLE_SCHEMA.to_string(),
        table: "trips".to_string(),
        rows,
    };
    if exists {
        Json(body).into_response()
    } else {
        (StatusCode::CREATED, Json(body)).into_response()
    }
}

#[cfg(test)]
mod tests {
    use super::{count_sql, exists_sql, trips_sql};

    #[test]
    fn trips_sql_is_the_measured_generated_shape() {
        let sql = trips_sql("playground");
        assert!(
            sql.starts_with(
                "CREATE TABLE IF NOT EXISTS \"playground\".\"samples\".trips AS SELECT"
            ),
            "{sql}"
        );
        assert!(
            sql.contains("FROM UNNEST(sequence(1, 10000)) AS t(id)"),
            "{sql}"
        );
        assert!(sql.contains("AS pickup_time"), "{sql}");
        assert!(sql.contains("AS zone"), "{sql}");
        assert!(
            !sql.to_lowercase().contains("random"),
            "the sample must be the same on every install: {sql}"
        );
        assert_eq!(
            sql,
            trips_sql("playground"),
            "the SQL must not change between calls"
        );
    }

    #[test]
    fn exists_sql_asks_the_catalogs_information_schema() {
        let sql = exists_sql("playground");
        assert!(
            sql.contains("\"playground\".information_schema.tables"),
            "{sql}"
        );
        assert!(sql.contains("table_schema = 'samples'"), "{sql}");
        assert!(sql.contains("table_name = 'trips'"), "{sql}");
    }

    #[test]
    fn count_sql_names_the_sample_table() {
        assert_eq!(
            count_sql("playground"),
            "SELECT count(*) FROM \"playground\".\"samples\".trips"
        );
    }
}
